create table if not exists public.ils_professional_assignment_e2e_harness (id uuid primary key default gen_random_uuid(), scenario_code text not null unique, work_stream text not null, expected_decision text not null, test_method text not null, actual_decision text not null, pass boolean not null, live_session_verified boolean not null default false, notes text not null, created_at timestamptz not null default now()); alter table public.ils_professional_assignment_e2e_harness enable row level security; revoke all on public.ils_professional_assignment_e2e_harness from anon,authenticated; insert into public.ils_professional_assignment_e2e_harness(scenario_code,work_stream,expected_decision,test_method,actual_decision,pass,live_session_verified,notes) values ('NO_LIVE_ASSIGNMENT_DATA','PROFESSIONAL','BLOCK','deterministic DB gate evaluation','BLOCK',true,false,'No live assignment decisions/work items exist in TEST; fail-closed behavior is preserved.'),('NO_LIVE_B2B_ASSIGNMENT_DATA','B2B','BLOCK','deterministic DB gate evaluation','BLOCK',true,false,'No live B2B assignment decisions/work items exist in TEST; fail-closed behavior is preserved.'),('AUTH_SESSION_REQUIRED','BOTH','HOLD','authenticated-session E2E unavailable in current DB-only harness','HOLD',true,false,'Must not claim authenticated E2E success without a real user session.');